import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M0 16V0h1a1 1 0 0 1 1 1v14a1 1 0 0 1-1 1zM15 0h1v16h-1a1 1 0 0 1-1-1V1a1 1 0 0 1 1-1M6.707 6.707a1 1 0 0 0-1.414-1.414l-2 2a1 1 0 0 0 0 1.414l2 2a1 1 0 0 0 1.414-1.414L5.414 8zm4-1.414a1 1 0 0 0-1.414 1.414L10.586 8 9.293 9.293a1 1 0 1 0 1.414 1.414l2-2a1 1 0 0 0 0-1.414z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M11.293 13.707a1 1 0 0 0 1.412 0l2.963-2.962a1 1 0 0 0 0-1.49l-2.963-2.962a.999.999 0 1 0-1.412 1.412L13.587 10l-2.294 2.295a1 1 0 0 0 0 1.412m-3.998 0a.999.999 0 0 0 1.412-1.412L6.413 10l2.294-2.295a.999.999 0 1 0-1.412-1.412L4.332 9.255l-.04.038A1 1 0 0 0 4 10a1 1 0 0 0 .332.745zM0 20V0h1a1 1 0 0 1 1 1v18a1 1 0 0 1-1 1zm20 0V0h-1a1 1 0 0 0-1 1v18a1 1 0 0 0 1 1z"] as readonly string[];

export const HorizontalInbetweenIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="horizontal-inbetween" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
HorizontalInbetweenIcon.displayName = `Blueprint6.Icon.HorizontalInbetweenIcon`;

/**
 * @deprecated Use {@link HorizontalInbetweenIcon} instead.
 */
export const HorizontalInbetween: typeof HorizontalInbetweenIcon = HorizontalInbetweenIcon;

export default HorizontalInbetweenIcon;
